@Test
public void testProxySettings() {
    Map<String, Object> map = new HashMap<>();
    map.put(RemoteProcessGroupSchema.PROXY_PORT_KEY, 1234);
    map.put(RemoteProcessGroupSchema.PROXY_USER_KEY, "user");
    RemoteProcessGroupSchema remoteProcessGroupSchema = new RemoteProcessGroupSchema(map);
    assertTrue(remoteProcessGroupSchema.getValidationIssues().contains(BaseSchema.getIssueText(RemoteProcessGroupSchema.PROXY_PORT_KEY, remoteProcessGroupSchema.getWrapperName(), RemoteProcessGroupSchema.EXPECTED_PROXY_HOST_IF_PROXY_PORT)));
    assertTrue(remoteProcessGroupSchema.getValidationIssues().contains(BaseSchema.getIssueText(RemoteProcessGroupSchema.PROXY_USER_KEY, remoteProcessGroupSchema.getWrapperName(), RemoteProcessGroupSchema.EXPECTED_PROXY_HOST_IF_PROXY_USER)));
    map.remove(RemoteProcessGroupSchema.PROXY_USER_KEY);
    map.put(RemoteProcessGroupSchema.PROXY_HOST_KEY, "host");
    remoteProcessGroupSchema = new RemoteProcessGroupSchema(map);
    assertFalse(remoteProcessGroupSchema.getValidationIssues().contains(BaseSchema.getIssueText(RemoteProcessGroupSchema.PROXY_PORT_KEY, remoteProcessGroupSchema.getWrapperName(), RemoteProcessGroupSchema.EXPECTED_PROXY_HOST_IF_PROXY_PORT)));
    assertTrue(remoteProcessGroupSchema.getValidationIssues().contains(BaseSchema.getIssueText(RemoteProcessGroupSchema.PROXY_HOST_KEY, remoteProcessGroupSchema.getWrapperName(), RemoteProcessGroupSchema.S2S_PROXY_REQUIRES_HTTP)));
    map.put(RemoteProcessGroupSchema.PROXY_PASSWORD_KEY, "password");
    remoteProcessGroupSchema = new RemoteProcessGroupSchema(map);
    assertTrue(remoteProcessGroupSchema.getValidationIssues().contains(BaseSchema.getIssueText(RemoteProcessGroupSchema.PROXY_PASSWORD_KEY, remoteProcessGroupSchema.getWrapperName(), RemoteProcessGroupSchema.EXPECTED_PROXY_USER_IF_PROXY_PASSWORD)));
    map.remove(RemoteProcessGroupSchema.PROXY_PASSWORD_KEY);
    map.put(RemoteProcessGroupSchema.PROXY_USER_KEY, "user");
    remoteProcessGroupSchema = new RemoteProcessGroupSchema(map);
    assertTrue(remoteProcessGroupSchema.getValidationIssues().contains(BaseSchema.getIssueText(RemoteProcessGroupSchema.PROXY_USER_KEY, remoteProcessGroupSchema.getWrapperName(), RemoteProcessGroupSchema.EXPECTED_PROXY_PASSWORD_IF_PROXY_USER)));
    map.put(RemoteProcessGroupSchema.PROXY_PASSWORD_KEY, "password");
