@Test
public void testSensitiveParameter() {
    final Map<String, Parameter> parameters = new HashMap<>();
    parameters.put("param", new Parameter(new ParameterDescriptor.Builder().name("param").build(), "value"));
    parameters.put("sensi", new Parameter(new ParameterDescriptor.Builder().name("sensi").sensitive(true).build(), "secret"));
    final ParameterLookup parameterLookup = new ParameterLookup() {

        @Override
        public Optional<Parameter> getParameter(final String parameterName) {
            return Optional.ofNullable(parameters.get(parameterName));
        }

        @Override
        public long getVersion() {
            return 0;
        }

        @Override
        public boolean isEmpty() {
            return parameters.isEmpty();
        }
    };
    final String value = Query.prepare("#{param}").evaluateExpressions(new StandardEvaluationContext(Collections.emptyMap(), Collections.emptyMap(), parameterLookup), null);
    assertEquals("value", value);
    final String secret = Query.prepare("#{sensi}").evaluateExpressions(new StandardEvaluationContext(Collections.emptyMap(), Collections.emptyMap(), parameterLookup), null);
    assertEquals("secret", secret);
    final String invalid = Query.prepare("${#{sensi}}").evaluateExpressions(new StandardEvaluationContext(Collections.emptyMap(), Collections.emptyMap(), parameterLookup), null);
    assertEquals("", invalid);
}

@Test
public void testVariableImpacted() {
    final Set<String> attr = new HashSet<>();
    attr.add("attr");
    final Set<String> attr2 = new HashSet<>();
    attr2.add("attr");
    attr2.add("attr2");
    final Set<String> abc = new HashSet<>();
    abc.add("a");
    abc.add("b");
    abc.add("c");
    assertTrue(Query.prepare("${attr}").getVariableImpact().isImpacted("attr"));
    assertFalse(Query.prepare("${attr}").getVariableImpact().isImpacted("attr2"));
    assertTrue(Query.prepare("${attr:trim():toUpper():equals('abc')}").getVariableImpact().isImpacted("attr"));
    assertFalse(Query.prepare("${anyAttribute('a', 'b', 'c'):equals('hello')}").getVariableImpact().isImpacted("attr"));
    assertTrue(Query.prepare("${anyAttribute('a', 'b', 'c'):equals('hello')}").getVariableImpact().isImpacted("a"));
    assertTrue(Query.prepare("${anyAttribute('a', 'b', 'c'):equals('hello')}").getVariableImpact().isImpacted("b"));
    assertTrue(Query.prepare("${anyAttribute('a', 'b', 'c'):equals('hello')}").getVariableImpact().isImpacted("c"));
    assertFalse(Query.prepare("${allAttributes('a', 'b', 'c'):equals('hello')}").getVariableImpact().isImpacted("attr"));
    assertTrue(Query.prepare("${allAttributes('a', 'b', 'c'):equals('hello')}").getVariableImpact().isImpacted("a"));
    assertTrue(Query.prepare("${allAttributes('a', 'b', 'c'):equals('hello')}").getVariableImpact().isImpacted("b"));
    assertTrue(Query.prepare("${allAttributes('a', 'b', 'c'):equals('hello')}").getVariableImpact().isImpacted("c"));
    assertTrue(Query.prepare("${attr:equals('${attr2}')}").getVariableImpact().isImpacted("attr"));
    assertTrue(Query.prepare("${attr:equals('${attr2}')}").getVariableImpact().isImpacted("attr2"));
    assertFalse(Query.prepare("${attr:equals('${attr2}')}").getVariableImpact().isImpacted("attr3"));
    assertTrue(Query.prepare("${allMatchingAttributes('a.*'):equals('hello')}").getVariableImpact().isImpacted("attr"));
    assertTrue(Query.prepare("${anyMatchingAttribute('a.*'):equals('hello')}").getVariableImpact().isImpacted("attr"));
}

@Test
public void testIsExpressionLanguagePresent() {
    assertFalse(Query.prepare("value").isExpressionLanguagePresent());
    assertFalse(Query.prepare("").isExpressionLanguagePresent());
    assertTrue(Query.prepare("${variable}").isExpressionLanguagePresent());
    assertTrue(Query.prepare("${hostname()}").isExpressionLanguagePresent());
    assertTrue(Query.prepare("${hostname():equals('localhost')}").isExpressionLanguagePresent());
    assertTrue(Query.prepare("prefix-${hostname()}").isExpressionLanguagePresent());
    assertTrue(Query.prepare("${hostname()}-suffix").isExpressionLanguagePresent());
    assertTrue(Query.prepare("${variable1}${hostname()}${variable2}").isExpressionLanguagePresent());
    assertTrue(Query.prepare("${${variable}}").isExpressionLanguagePresent());
    assertFalse(Query.prepare("${}").isExpressionLanguagePresent());
    assertFalse(Query.prepare("#{param}").isExpressionLanguagePresent());
}

@Test
@SuppressWarnings("unchecked")
public void testCreateCustomVariableRegistry() {
    final VariableRegistry variableRegistry = VariableRegistry.ENVIRONMENT_SYSTEM_REGISTRY;
    final ValueLookup initialLookup = new ValueLookup(variableRegistry, null);
    assertTrue(initialLookup.containsKey("PATH"));
    assertFalse(initialLookup.containsKey("fake.property.3"));
    assertFalse(initialLookup.containsKey("fake"));
    final Map<String, String> otherAttrs = new HashMap<>();
    otherAttrs.put("fake", "test");
    otherAttrs.put("fake.property.3", "test me out 3, test me out 4");
    final ValueLookup newLookup = new ValueLookup(variableRegistry, null, otherAttrs);
    assertTrue(newLookup.containsKey("PATH"));
    assertTrue(newLookup.containsKey("fake.property.3"));
    assertEquals("test me out 3, test me out 4", newLookup.get("fake.property.3"));
    assertEquals("test", newLookup.get("fake"));
    assertFalse(newLookup.containsKey("filename"));
    final FlowFile fakeFile = createFlowFile();
    final ValueLookup ffLookup = new ValueLookup(variableRegistry, fakeFile, otherAttrs);
    assertTrue(ffLookup.containsKey("filename"));
    assertEquals("test", ffLookup.get("fake"));
    assertEquals("1", ffLookup.get("flowFileId"));
    assertEquals("50", ffLookup.get("fileSize"));
    assertEquals("1000", ffLookup.get("entryDate"));
    assertEquals("10000", ffLookup.get("lineageStartDate"));
    assertEquals("fakefile.txt", ffLookup.get("filename"));
    final Map<String, String> overrides = new HashMap<>();
    overrides.put("fake", "the real deal");
    final ValueLookup overriddenLookup = new ValueLookup(variableRegistry, fakeFile, overrides, otherAttrs);
    assertTrue(overriddenLookup.containsKey("filename"));
    assertEquals("the real deal", overriddenLookup.get("fake"));
    assertEquals("1", overriddenLookup.get("flowFileId"));
    assertEquals("50", overriddenLookup.get("fileSize"));
    assertEquals("1000", overriddenLookup.get("entryDate"));
    assertEquals("10000", overriddenLookup.get("lineageStartDate"));
    assertEquals("fakefile.txt", overriddenLookup.get("filename"));
    assertEquals("original", overriddenLookup.get("override me"));
    final Map<String, String> newOverrides = new HashMap<>();
    newOverrides.put("fake", "the real deal");
    newOverrides.put("override me", "done you are now overridden");
    final ValueLookup newOverriddenLookup = new ValueLookup(variableRegistry, fakeFile, newOverrides, otherAttrs);
    assertTrue(newOverriddenLookup.containsKey("filename"));
    assertEquals("the real deal", newOverriddenLookup.get("fake"));
    assertEquals("1", newOverriddenLookup.get("flowFileId"));
    assertEquals("50", newOverriddenLookup.get("fileSize"));
    assertEquals("1000", newOverriddenLookup.get("entryDate"));
    assertEquals("10000", newOverriddenLookup.get("lineageStartDate"));
    assertEquals("fakefile.txt", newOverriddenLookup.get("filename"));
    assertEquals("done you are now overridden", newOverriddenLookup.get("override me"));
}

