    }
    int[] expectedValues = new int[] { 0, 2, 4, 5, 6, 7, 9 };
    assertEquals(expectedValues.length, fieldValues.size());
    for (int i = 0; i < expectedValues.length; i++) {
        assertEquals(expectedValues[i], fieldValues.get(i).getValue());
    }
