@Test(timeout = 10_000)
public void testWaitForSync() throws Exception {
    try (RocksDBMetronome db = new RocksDBMetronome.Builder().setStoragePath(temporaryFolder.newFolder().toPath()).setSyncMillis(// effectively disable the auto-sync
    Long.MAX_VALUE).build()) {
        db.initialize();
        Future<Boolean> future = executor.submit(() -> {
            db.waitForSync();
            return true;
        });
        // the future should still be blocked waiting for sync to happen
        assertFalse(future.isDone());
        // give the future time to wake up and complete
        while (!future.isDone()) {
            // TESTING NOTE: this is inside a loop to address a minor *testing* race condition where our first doSync() could happen before the future runs,
            // meaning waitForSync() would be left waiting on another doSync() that never comes...
            // do the sync (which would normally happen via the db's internal executor)
            db.doSync();
            Thread.sleep(25);
        }
        // the future should no longer be blocked
        assertTrue(future.isDone());
    }
}

@Test(timeout = 10_000)
public void testWaitForSyncWithValue() throws Exception {
    try (RocksDBMetronome db = new RocksDBMetronome.Builder().setStoragePath(temporaryFolder.newFolder().toPath()).setSyncMillis(// effectively disable the auto-sync
    Long.MAX_VALUE).build()) {
        db.initialize();
        int syncCounterValue = db.getSyncCounterValue();
        // "wait" for one before current counter value... should not block
        db.waitForSync(syncCounterValue - 1);
        // wait for current value... should block (because auto-sync isn't happening)
        assertBlocks(db, syncCounterValue);
        // do the sync (which would normally happen via the db's internal executor)
        db.doSync();
        // "wait" for initial value... should now not block
        db.waitForSync(syncCounterValue);
        // wait for current value again... should block (because auto-sync isn't happening)
        assertBlocks(db, db.getSyncCounterValue());
    }
}

@Test
public void testReadExactlyOnceFields() throws IOException {
    final List<RecordField> fields = new ArrayList<>();
    fields.add(new SimpleRecordField("int", FieldType.INT, Repetition.EXACTLY_ONE));
    fields.add(new SimpleRecordField("boolean", FieldType.BOOLEAN, Repetition.EXACTLY_ONE));
    fields.add(new SimpleRecordField("byte array", FieldType.BYTE_ARRAY, Repetition.EXACTLY_ONE));
    fields.add(new SimpleRecordField("long", FieldType.LONG, Repetition.EXACTLY_ONE));
    fields.add(new SimpleRecordField("string", FieldType.STRING, Repetition.EXACTLY_ONE));
    fields.add(new SimpleRecordField("long string", FieldType.LONG_STRING, Repetition.EXACTLY_ONE));
    fields.add(new ComplexRecordField("complex", Repetition.EXACTLY_ONE, new SimpleRecordField("key", FieldType.STRING, Repetition.EXACTLY_ONE), new SimpleRecordField("value", FieldType.STRING, Repetition.EXACTLY_ONE)));
    fields.add(new MapRecordField("map", new SimpleRecordField("key", FieldType.STRING, Repetition.EXACTLY_ONE), new SimpleRecordField("value", FieldType.STRING, Repetition.ZERO_OR_ONE), Repetition.EXACTLY_ONE));
    fields.add(new UnionRecordField("union1", Repetition.EXACTLY_ONE, Arrays.asList(new RecordField[] { new SimpleRecordField("one", FieldType.STRING, Repetition.EXACTLY_ONE), new SimpleRecordField("two", FieldType.INT, Repetition.EXACTLY_ONE) })));
    fields.add(new UnionRecordField("union2", Repetition.EXACTLY_ONE, Arrays.asList(new RecordField[] { new SimpleRecordField("one", FieldType.STRING, Repetition.EXACTLY_ONE), new SimpleRecordField("two", FieldType.INT, Repetition.EXACTLY_ONE) })));
    final RecordSchema schema = new RecordSchema(fields);
    final SchemaRecordReader reader = SchemaRecordReader.fromSchema(schema, new NoOpFieldCache());
    final byte[] buffer;
    try (final ByteArrayOutputStream baos = new ByteArrayOutputStream();
        final DataOutputStream dos = new DataOutputStream(baos)) {
        // sentinel byte
        dos.write(1);
        dos.writeInt(42);
        dos.writeBoolean(true);
        final byte[] array = "hello".getBytes();
        dos.writeInt(array.length);
        dos.write(array);
        dos.writeLong(42L);
        dos.writeUTF("hello");
        final String longString = "hello";
        final byte[] longStringArray = longString.getBytes(StandardCharsets.UTF_8);
        dos.writeInt(longStringArray.length);
        dos.write(longStringArray);
        dos.writeUTF("key");
        dos.writeUTF("value");
        dos.writeInt(2);
        dos.writeUTF("key1");
        dos.writeBoolean(true);
        dos.writeUTF("value1");
        dos.writeUTF("key2");
        dos.writeBoolean(false);
        dos.writeUTF("one");
        dos.writeUTF("hello");
        dos.writeUTF("two");
        dos.writeInt(42);
        buffer = baos.toByteArray();
    }
    try (final ByteArrayInputStream in = new ByteArrayInputStream(buffer)) {
        final Record record = reader.readRecord(in);
        assertNotNull(record);
        assertEquals(42, record.getFieldValue("int"));
        assertTrue((boolean) record.getFieldValue("boolean"));
        assertTrue(Arrays.equals("hello".getBytes(), (byte[]) record.getFieldValue("byte array")));
        assertEquals(42L, record.getFieldValue("long"));
        assertEquals("hello", record.getFieldValue("string"));
        assertEquals("hello", record.getFieldValue("long string"));
        final Record complexRecord = (Record) record.getFieldValue("complex");
        assertEquals("key", complexRecord.getFieldValue(new SimpleRecordField("key", FieldType.STRING, Repetition.EXACTLY_ONE)));
        assertEquals("value", complexRecord.getFieldValue(new SimpleRecordField("value", FieldType.STRING, Repetition.EXACTLY_ONE)));
        final Map<String, String> map = new HashMap<>();
        map.put("key1", "value1");
        map.put("key2", null);
        assertEquals(map, record.getFieldValue("map"));
        assertEquals("hello", record.getFieldValue("union1"));
        assertEquals(42, record.getFieldValue("union2"));
    }
}

