public void testAddRemoveClearUsers() {
    final AccessPolicy.Builder builder = new AccessPolicy.Builder().identifier("1").resource(TEST_RESOURCE).addUser("user1").action(RequestAction.READ);
    final AccessPolicy policy1 = builder.build();
    assertEquals(1, policy1.getUsers().size());
