@Test
public void testInitialisation() {
    final ExtendedSequenceNumber esn = new ExtendedSequenceNumber(InitialPositionInStream.AT_TIMESTAMP.toString(), 123L);
    final InitializationInput initializationInput = new InitializationInput().withExtendedSequenceNumber(esn).withShardId("shard-id");
