    final ProcessRecordsInput processRecordsInput = new ProcessRecordsInput().withRecords(Arrays.asList(new Record().withApproximateArrivalTimestamp(null).withPartitionKey("partition-1").withSequenceNumber("1").withData(ByteBuffer.wrap("record-1".getBytes(StandardCharsets.UTF_8))), kinesisRecord, new Record().withApproximateArrivalTimestamp(null).withPartitionKey("partition-3").withSequenceNumber("3").withData(ByteBuffer.wrap("record-3".getBytes(StandardCharsets.UTF_8))))).withCheckpointer(checkpointer).withCacheEntryTime(Instant.now().minus(1, ChronoUnit.MINUTES)).withCacheExitTime(Instant.now().minus(1, ChronoUnit.SECONDS)).withMillisBehindLatest(100L);
