    assertThat(ae.getMessage(), containsString("'Property Name' validated against ' ' is invalid because Invalid attribute key: <Empty String>\n"));
    // invalid property names
    assertThat(ae.getMessage(), containsString("'withPrefixNotAllowed' validated against 'a-value' is invalid because Property name must not have a prefix of \"with\", " + "must start with a letter and contain only letters, numbers or underscores\n"));
    assertThat(ae.getMessage(), containsString("'unknownProperty' validated against 'a-third-value' is invalid because Kinesis Client Library Configuration property with name " + "UnknownProperty does not exist or is not writable\n"));
    assertThat(ae.getMessage(), containsString("'toString' validated against 'cannot-call' is invalid because Kinesis Client Library Configuration property with name " + "ToString does not exist or is not writable\n"));
    // invalid property names (cannot use nested/indexed/mapped properties via BeanUtils)
    assertThat(ae.getMessage(), containsString("'no.allowed' validated against 'no-.' is invalid because Property name must not have a prefix of \"with\", " + "must start with a letter and contain only letters, numbers or underscores\n"));
    assertThat(ae.getMessage(), containsString("'no[allowed' validated against 'no-[' is invalid because Property name must not have a prefix of \"with\", " + "must start with a letter and contain only letters, numbers or underscores\n"));
    assertThat(ae.getMessage(), containsString("'no]allowed' validated against 'no-]' is invalid because Property name must not have a prefix of \"with\", " + "must start with a letter and contain only letters, numbers or underscores\n"));
    assertThat(ae.getMessage(), containsString("'no(allowed' validated against 'no-(' is invalid because Property name must not have a prefix of \"with\", " + "must start with a letter and contain only letters, numbers or underscores\n"));
    assertThat(ae.getMessage(), containsString("'no)allowed' validated against 'no-)' is invalid because Property name must not have a prefix of \"with\", " + "must start with a letter and contain only letters, numbers or underscores\n"));
    // can't override static properties
    assertThat(ae.getMessage(), containsString("'regionName' validated against 'af-south-1' is invalid because Use \"Region\" instead of a dynamic property\n"));
    assertThat(ae.getMessage(), containsString("'timestampAtInitialPositionInStream' validated against '2021-01-01 00:00:00' is invalid because Use \"Stream Position Timestamp\" instead of a dynamic property\n"));
    assertThat(ae.getMessage(), containsString("'initialPositionInStream' validated against 'AT_TIMESTAMP' is invalid because Use \"Initial Stream Position\" instead of a dynamic property\n"));
    assertThat(ae.getMessage(), containsString("'dynamoDBEndpoint' validated against 'http://localhost:4566/dynamodb' is invalid because Use \"DynamoDB Override\" instead of a dynamic property\n"));
    assertThat(ae.getMessage(), containsString("'kinesisEndpoint' validated against 'http://localhost:4566/kinesis' is invalid because Use \"Endpoint Override URL\" instead of a dynamic property\n"));
    // invalid parameter conversions
    assertThat(ae.getMessage(), containsString("'dynamoDBClientConfig' validated against 'too-complex' is invalid because Kinesis Client Library Configuration property " + "with name DynamoDBClientConfig cannot be used with value \"too-complex\" : " + "Cannot invoke com.amazonaws.services.kinesis.clientlibrary.lib.worker.KinesisClientLibConfiguration.withDynamoDBClientConfig on bean class " + "'class com.amazonaws.services.kinesis.clientlibrary.lib.worker.KinesisClientLibConfiguration' - argument type mismatch - " + "had objects of type \"java.lang.String\" but expected signature \"com.amazonaws.ClientConfiguration\"\n"));
    assertThat(ae.getMessage(), containsString("'shutdownGraceMillis' validated against 'not-long' is invalid because " + "Kinesis Client Library Configuration property with name ShutdownGraceMillis " + "cannot be used with value \"not-long\" : Value of ShutdownGraceMillis should be positive, but current value is 0\n"));
