@Test
public void testValidatePrincipalAndKeytab() {
    final ComponentLog log = Mockito.mock(ComponentLog.class);
    final Configuration config = new Configuration();
    // no security enabled in config so doesn't matter what principal, keytab, and password are
    List<ValidationResult> results = KerberosProperties.validatePrincipalWithKeytabOrPassword("test", config, null, null, null, log);
    Assert.assertEquals(0, results.size());
    results = KerberosProperties.validatePrincipalWithKeytabOrPassword("test", config, "principal", null, null, log);
    Assert.assertEquals(0, results.size());
    results = KerberosProperties.validatePrincipalWithKeytabOrPassword("test", config, "principal", "keytab", null, log);
    Assert.assertEquals(0, results.size());
    results = KerberosProperties.validatePrincipalWithKeytabOrPassword("test", config, "principal", null, "password", log);
    Assert.assertEquals(0, results.size());
    results = KerberosProperties.validatePrincipalWithKeytabOrPassword("test", config, "principal", "keytab", "password", log);
    Assert.assertEquals(0, results.size());
    // change the config to have kerberos turned on
    config.set("hadoop.security.authentication", "kerberos");
    config.set("hadoop.security.authorization", "true");
    // security is enabled, no principal, keytab, or password provided
    results = KerberosProperties.validatePrincipalWithKeytabOrPassword("test", config, null, null, null, log);
    Assert.assertEquals(2, results.size());
    // security is enabled, keytab provided, no principal or password provided
    results = KerberosProperties.validatePrincipalWithKeytabOrPassword("test", config, null, "keytab", null, log);
    Assert.assertEquals(1, results.size());
    // security is enabled, password provided, no principal or keytab provided
    results = KerberosProperties.validatePrincipalWithKeytabOrPassword("test", config, null, null, "password", log);
    Assert.assertEquals(1, results.size());
    // security is enabled, no principal provided, keytab and password provided
    results = KerberosProperties.validatePrincipalWithKeytabOrPassword("test", config, null, "keytab", "password", log);
    Assert.assertEquals(2, results.size());
    // security is enabled, principal provided, no keytab or password provided
    results = KerberosProperties.validatePrincipalWithKeytabOrPassword("test", config, "principal", null, null, log);
    Assert.assertEquals(1, results.size());
    // security is enabled, principal and keytab provided, no password provided
    results = KerberosProperties.validatePrincipalWithKeytabOrPassword("test", config, "principal", "keytab", null, log);
    Assert.assertEquals(0, results.size());
    // security is enabled, no keytab provided, principal and password provided
    results = KerberosProperties.validatePrincipalWithKeytabOrPassword("test", config, "principal", null, "password", log);
    Assert.assertEquals(0, results.size());
    // security is enabled, principal, keytab, and password provided
    results = KerberosProperties.validatePrincipalWithKeytabOrPassword("test", config, "principal", "keytab", "password", log);
    Assert.assertEquals(1, results.size());
}

/**
 * <p>
 * Ensures that files are listed when those are old enough:
 * <li>Files with last modified timestamp those are old enough to determine
 * that those are completely written and no further files are expected to be
 * added with the same timestamp.</li>
 * <li>This behavior is expected when a processor is scheduled less
 * frequently, such as hourly or daily.</li>
 * </p>
 */
@Test
public void testAllExistingEntriesEmittedOnFirstIteration() throws Exception {
    final long oldTimestamp = System.currentTimeMillis() - getSleepMillis(TimeUnit.MILLISECONDS);
    // These entries have existed before the processor runs at the first time.
    proc.addEntity("name", "id", oldTimestamp);
    proc.addEntity("name", "id2", oldTimestamp);
    // First run, the above listed entries should be emitted since it has existed.
    runner.run();
    runner.assertAllFlowFilesTransferred(ConcreteListProcessor.REL_SUCCESS, 2);
    runner.clearTransferState();
    // Ensure we have covered the necessary lag period to avoid issues where the processor was immediately scheduled to run again
    Thread.sleep(DEFAULT_SLEEP_MILLIS);
    // Run again without introducing any new entries
    runner.run();
    runner.assertAllFlowFilesTransferred(ConcreteListProcessor.REL_SUCCESS, 0);
}

