@Test
public void testGetAllUsersGroupsPolicies() throws Exception {
    writeFile(primaryAuthorizations, AUTHORIZATIONS);
    writeFile(primaryTenants, TENANTS);
    authorizer.onConfigured(configurationContext);
    final Set<Group> groups = authorizer.getGroups();
    assertEquals(2, groups.size());
    boolean foundGroup1 = false;
    boolean foundGroup2 = false;
    for (Group group : groups) {
        if (group.getIdentifier().equals("group-1") && group.getName().equals("group-1") && group.getUsers().size() == 1 && group.getUsers().contains("user-1")) {
            foundGroup1 = true;
        } else if (group.getIdentifier().equals("group-2") && group.getName().equals("group-2") && group.getUsers().size() == 1 && group.getUsers().contains("user-2")) {
            foundGroup2 = true;
        }
    }
    assertTrue(foundGroup1);
    assertTrue(foundGroup2);
    final Set<User> users = authorizer.getUsers();
    assertEquals(2, users.size());
    boolean foundUser1 = false;
    boolean foundUser2 = false;
    for (User user : users) {
        if (user.getIdentifier().equals("user-1") && user.getIdentity().equals("user-1")) {
            foundUser1 = true;
        } else if (user.getIdentifier().equals("user-2") && user.getIdentity().equals("user-2")) {
            foundUser2 = true;
        }
    }
    assertTrue(foundUser1);
    assertTrue(foundUser2);
    final Set<AccessPolicy> policies = authorizer.getAccessPolicies();
    assertEquals(2, policies.size());
    boolean foundPolicy1 = false;
    boolean foundPolicy2 = false;
    for (AccessPolicy policy : policies) {
        if (policy.getIdentifier().equals("policy-1") && policy.getResource().equals("/flow") && policy.getAction() == RequestAction.READ && policy.getGroups().size() == 2 && policy.getGroups().contains("group-1") && policy.getGroups().contains("group-2") && policy.getUsers().size() == 1 && policy.getUsers().contains("user-1")) {
            foundPolicy1 = true;
        } else if (policy.getIdentifier().equals("policy-2") && policy.getResource().equals("/flow") && policy.getAction() == RequestAction.WRITE && policy.getGroups().size() == 0 && policy.getUsers().size() == 1 && policy.getUsers().contains("user-2")) {
            foundPolicy2 = true;
        }
    }
    assertTrue(foundPolicy1);
    assertTrue(foundPolicy2);
}

