    assertEquals(BUCKET, flowFile.getAttribute(BUCKET_ATTR));
    assertEquals(KEY, flowFile.getAttribute(KEY_ATTR));
    assertEquals(CACHE_CONTROL, flowFile.getAttribute(CACHE_CONTROL_ATTR));
