    runner.setProperty(ScanHBase.TIME_RANGE_MAX, "1111111110");
    runner.setProperty(ScanHBase.LIMIT_ROWS, "10");
    runner.setProperty(ScanHBase.REVERSED_SCAN, "false");
    runner.setProperty(ScanHBase.BULK_SIZE, "10");
