    verify(mockLease, times(0)).publish(any(FlowFile.class), any(Map.class), eq(null), any(byte[].class), eq(TOPIC_NAME), any(InFlightMessageTracker.class), nullable(Integer.class));
    verify(mockLease, times(1)).complete();
    verify(mockLease, times(0)).poison();
    verify(mockLease, times(1)).close();
    runner.assertAllFlowFilesContainAttribute("msg.count");
    assertEquals(1, runner.getFlowFilesForRelationship(PublishKafkaRecord_1_0.REL_SUCCESS).stream().filter(ff -> ff.getAttribute("msg.count").equals("10")).count());
    assertEquals(1, runner.getFlowFilesForRelationship(PublishKafkaRecord_1_0.REL_SUCCESS).stream().filter(ff -> ff.getAttribute("msg.count").equals("20")).count());
}

