@Test
public void testRecordFormat() throws IOException, InitializationException {
    MockKafkaRecordSink_1_0 task = initTask();
    List<RecordField> recordFields = Arrays.asList(new RecordField("field1", RecordFieldType.INT.getDataType()), new RecordField("field2", RecordFieldType.STRING.getDataType()));
    RecordSchema recordSchema = new SimpleRecordSchema(recordFields);
    Map<String, Object> row1 = new HashMap<>();
    row1.put("field1", 15);
    row1.put("field2", "Hello");
    Map<String, Object> row2 = new HashMap<>();
    row2.put("field1", 6);
    row2.put("field2", "World!");
    RecordSet recordSet = new ListRecordSet(recordSchema, Arrays.asList(new MapRecord(recordSchema, row1), new MapRecord(recordSchema, row2)));
    task.sendData(recordSet, new HashMap<>(), true);
    assertEquals(1, task.dataSent.size());
    String[] lines = new String(task.dataSent.get(0)).split("\n");
    assertNotNull(lines);
    assertEquals(2, lines.length);
    String[] data = lines[0].split(",");
    // In the MockRecordWriter all values are strings
    assertEquals("15", data[0]);
    assertEquals("Hello", data[1]);
    data = lines[1].split(",");
    assertEquals("6", data[0]);
    assertEquals("World!", data[1]);
}

