public void testConsumerNotCreatedOnDemandWhenUsingStaticAssignment() {
    final ConsumerPool staticAssignmentPool = new ConsumerPool(1, null, false, Collections.emptyMap(), Collections.singletonList("nifi"), 100L, "utf-8", "ssl", "localhost", logger, true, StandardCharsets.UTF_8, null, new int[] { 1, 2, 3 }) {

