        if (decoder.process(b)) {
            frames = decoder.getFrames();
            break;
        }
    }
    frame = frames.get(1);
    Assert.assertNotNull(frame);
    Assert.assertEquals(0x31, frame.getVersion());
    Assert.assertEquals(0x44, frame.getFrameType());
