            found2 = true;
        } else if (seqNum.equals("3")) {
            found3 = true;
        } else if (seqNum.equals("4")) {
            found4 = true;
        }
    }
    Assert.assertTrue(found1);
    Assert.assertTrue(found2);
    Assert.assertTrue(found3);
    Assert.assertTrue(found4);
}

