    runner.run();
    runner.assertAllFlowFilesTransferred(ResizeImage.REL_SUCCESS, 1);
    mff = runner.getFlowFilesForRelationship(ResizeImage.REL_SUCCESS).get(0);
    data = mff.toByteArray();
