@Test
public void testOnTrigger() throws IOException, InterruptedException, InitializationException {
    testedReportingTask.initialize(reportingInitContextStub);
    testedReportingTask.onScheduled(configurationContextStub);
    reportingContextStub.getEventAccess().setProcessGroupStatus(rootGroupStatus);
    testedReportingTask.onTrigger(reportingContextStub);
    String content = getMetrics();
    Assert.assertTrue(content.contains("nifi_amount_flowfiles_received{instance=\"localhost\",component_type=\"RootProcessGroup\",component_name=\"root\",component_id=\"1234\",parent_id=\"\",} 5.0"));
    Assert.assertTrue(content.contains("nifi_amount_threads_active{instance=\"localhost\",component_type=\"RootProcessGroup\",component_name=\"root\",component_id=\"1234\",parent_id=\"\",} 5.0"));
    Assert.assertTrue(content.contains("nifi_amount_threads_active{instance=\"localhost\",component_type=\"ProcessGroup\",component_name=\"nestedPG\",component_id=\"3378\",parent_id=\"1234\",} 2.0"));
    // Rename the component
    rootGroupStatus.setName("rootroot");
    content = getMetrics();
    Assert.assertFalse(content.contains("nifi_amount_flowfiles_received{instance=\"localhost\",component_type=\"RootProcessGroup\",component_name=\"root\",component_id=\"1234\",parent_id=\"\",} 5.0"));
    Assert.assertFalse(content.contains("nifi_amount_threads_active{instance=\"localhost\",component_type=\"RootProcessGroup\",component_name=\"root\",component_id=\"1234\",parent_id=\"\",} 5.0"));
    Assert.assertTrue(content.contains("nifi_amount_flowfiles_received{instance=\"localhost\",component_type=\"RootProcessGroup\",component_name=\"rootroot\",component_id=\"1234\",parent_id=\"\",} 5.0"));
    Assert.assertTrue(content.contains("nifi_amount_threads_active{instance=\"localhost\",component_type=\"RootProcessGroup\",component_name=\"rootroot\",component_id=\"1234\",parent_id=\"\",} 5.0"));
    try {
        testedReportingTask.OnStopped();
    } catch (Exception e) {
        // Ignore
    }
}

