@Test
public void testParseLocationsSingle() {
    final String swLon = "-122.75";
    final String swLat = "36.8";
    final String neLon = "-121.75";
    final String neLat = "37.8";
    final String locationString = swLon + "," + swLat + "," + neLon + "," + neLat;
    List<Location> locations = LocationUtil.parseLocations(locationString);
    Assert.assertEquals(1, locations.size());
    Location location = locations.get(0);
    Assert.assertEquals(new Double(location.southwestCoordinate().longitude()), Double.valueOf(swLon));
    Assert.assertEquals(new Double(location.southwestCoordinate().latitude()), Double.valueOf(swLat));
    Assert.assertEquals(new Double(location.northeastCoordinate().longitude()), Double.valueOf(neLon));
    Assert.assertEquals(new Double(location.northeastCoordinate().latitude()), Double.valueOf(neLat));
}

@Test
public void testParseLocationsMultiple() {
    final Location location1 = new Location(new Location.Coordinate(-122.75, 36.8), new Location.Coordinate(-121.75, 37.8));
    final Location location2 = new Location(new Location.Coordinate(-74, 40), new Location.Coordinate(-73, 41));
    final Location location3 = new Location(new Location.Coordinate(-64, 30), new Location.Coordinate(-63, 31));
    final Location location4 = new Location(new Location.Coordinate(-54, 20), new Location.Coordinate(-53, 21));
    final List<Location> expectedLocations = Arrays.asList(location1, location2, location3, location4);
    final String locationString = "-122.75,36.8,-121.75,37.8,-74,40,-73,41,-64,30,-63,31,-54,20,-53,21";
    List<Location> locations = LocationUtil.parseLocations(locationString);
    Assert.assertEquals(expectedLocations.size(), locations.size());
    for (Location expectedLocation : expectedLocations) {
        boolean found = false;
        for (Location location : locations) {
            if (location.northeastCoordinate().longitude() == expectedLocation.northeastCoordinate().longitude() && location.northeastCoordinate().latitude() == expectedLocation.northeastCoordinate().latitude() && location.southwestCoordinate().longitude() == expectedLocation.southwestCoordinate().longitude() && location.southwestCoordinate().latitude() == expectedLocation.southwestCoordinate().latitude()) {
                found = true;
                break;
            }
        }
        Assert.assertTrue(found);
    }
}

@Test
public void testAllFacetCategories() throws IOException {
    SolrClient solrClient = createSolrClient();
    TestRunner runner = createRunnerWithSolrClient(solrClient);
    runner.setProperty("facet", "true");
    runner.setProperty("facet.field", "integer_multi");
    runner.setProperty("facet.interval", "integer_single");
    runner.setProperty("facet.interval.set.1", "[4,7]");
    runner.setProperty("facet.interval.set.2", "[5,7]");
    runner.setProperty("facet.range", "created");
    runner.setProperty("facet.range.start", "NOW/MINUTE");
    runner.setProperty("facet.range.end", "NOW/MINUTE+1MINUTE");
    runner.setProperty("facet.range.gap", "+20SECOND");
    runner.setProperty("facet.query.1", "*:*");
    runner.setProperty("facet.query.2", "integer_multi:2");
    runner.setProperty("facet.query.3", "integer_multi:3");
    runner.enqueue(new ByteArrayInputStream(new byte[0]));
    runner.run();
    runner.assertTransferCount(QuerySolr.FACETS, 1);
    JsonReader reader = new JsonReader(new InputStreamReader(new ByteArrayInputStream(runner.getContentAsByteArray(runner.getFlowFilesForRelationship(QuerySolr.FACETS).get(0)))));
    reader.beginObject();
    while (reader.hasNext()) {
        String name = reader.nextName();
        if (name.equals("facet_queries")) {
            assertEquals(30, returnCheckSumForArrayOfJsonObjects(reader));
        } else if (name.equals("facet_fields")) {
            reader.beginObject();
            assertEquals(reader.nextName(), "integer_multi");
            assertEquals(returnCheckSumForArrayOfJsonObjects(reader), 30);
            reader.endObject();
        } else if (name.equals("facet_ranges")) {
            reader.beginObject();
            assertEquals(reader.nextName(), "created");
            assertEquals(returnCheckSumForArrayOfJsonObjects(reader), 10);
            reader.endObject();
        } else if (name.equals("facet_intervals")) {
            reader.beginObject();
            assertEquals(reader.nextName(), "integer_single");
            assertEquals(returnCheckSumForArrayOfJsonObjects(reader), 7);
            reader.endObject();
        }
    }
    reader.endObject();
    reader.close();
    solrClient.close();
}

