    final Map<String, String> expectedExtensions = new HashMap<>();
    expectedExtensions.put("1.7z", "");
    expectedExtensions.put("1.mdb", "");
    expectedExtensions.put("1.txt", "");
    expectedExtensions.put("1.csv", "");
    expectedExtensions.put("1.txt.bz2", "");
