        return true;
    }).when(sftpClient).mkdir(eq("/dir1/dir2/dir3"));
    final SFTPTransfer sftpTransfer = createSftpTransfer(processContext, sftpClient);
    final MockFlowFile flowFile = new MockFlowFile(0);
