    assertTrue(added2);
    final boolean contains = client.contains("test", serializer);
    final boolean contains2 = client.contains("test2", serializer);
    assertTrue(contains);
    assertTrue(contains2);
    final boolean addedAgain = client.addIfAbsent("test", serializer);
