    SimpleRecordSchema recordSchema1 = new SimpleRecordSchema(Arrays.asList(new RecordField("integer", RecordFieldType.INT.getDataType()), new RecordField("boolean", RecordFieldType.BOOLEAN.getDataType())));
    SimpleRecordSchema recordSchema2 = new SimpleRecordSchema(Arrays.asList(new RecordField("integer", RecordFieldType.INT.getDataType()), new RecordField("string", RecordFieldType.STRING.getDataType())));
    RecordSchema recordChoiceSchema = new SimpleRecordSchema(Arrays.asList(new RecordField("record", RecordFieldType.CHOICE.getChoiceDataType(RecordFieldType.ARRAY.getArrayDataType(RecordFieldType.RECORD.getRecordDataType(recordSchema1)), RecordFieldType.ARRAY.getArrayDataType(RecordFieldType.RECORD.getRecordDataType(recordSchema2))))));
    RecordSchema schema = new SimpleRecordSchema(Arrays.asList(new RecordField("dataCollection", RecordFieldType.ARRAY.getArrayDataType(RecordFieldType.RECORD.getRecordDataType(recordChoiceSchema)))));
    SimpleRecordSchema expectedChildSchema1 = new SimpleRecordSchema(Arrays.asList(new RecordField("integer", RecordFieldType.INT.getDataType()), new RecordField("boolean", RecordFieldType.BOOLEAN.getDataType())));
    SimpleRecordSchema expectedChildSchema2 = new SimpleRecordSchema(Arrays.asList(new RecordField("integer", RecordFieldType.INT.getDataType()), new RecordField("string", RecordFieldType.STRING.getDataType())));
    RecordSchema expectedRecordChoiceSchema = new SimpleRecordSchema(Arrays.asList(new RecordField("record", RecordFieldType.CHOICE.getChoiceDataType(RecordFieldType.ARRAY.getArrayDataType(RecordFieldType.RECORD.getRecordDataType(expectedChildSchema1)), RecordFieldType.ARRAY.getArrayDataType(RecordFieldType.RECORD.getRecordDataType(expectedChildSchema2))))));
    // Since the actual arrays have records with either (INT, BOOLEAN, STRING) or (INT, STRING, STRING)
    //  while the explicit schema defines only (INT, BOOLEAN) and (INT, STRING) we can't tell which record schema to chose
    //  so we take the first one (INT, BOOLEAN) - as best effort - for both cases
    SimpleRecordSchema expectedSelectedRecordSchemaForRecordsInBothArrays = expectedChildSchema1;
    List<Object> expected = Arrays.asList(new MapRecord(expectedRecordChoiceSchema, new HashMap<String, Object>() {

        {
            put("record", new Object[] { new MapRecord(expectedSelectedRecordSchemaForRecordsInBothArrays, new HashMap<String, Object>() {

                {
                    put("integer", 11);
                    put("boolean", true);
                    put("extraString", "extraStringValue11");
                }
            }), new MapRecord(expectedSelectedRecordSchemaForRecordsInBothArrays, new HashMap<String, Object>() {

                {
                    put("integer", 12);
                    put("boolean", false);
                    put("extraString", "extraStringValue12");
                }
            }) });
        }
    }), new MapRecord(expectedRecordChoiceSchema, new HashMap<String, Object>() {

        {
            put("record", new Object[] { new MapRecord(expectedSelectedRecordSchemaForRecordsInBothArrays, new HashMap<String, Object>() {

                {
                    put("integer", 21);
                    put("extraString", "extraStringValue21");
                    put("string", "stringValue21");
                }
            }), new MapRecord(expectedSelectedRecordSchemaForRecordsInBothArrays, new HashMap<String, Object>() {

                {
                    put("integer", 22);
                    put("extraString", "extraStringValue22");
                    put("string", "stringValue22");
                }
            }) });
        }
    }));
    // WHEN
    // THEN
    testReadRecords(jsonPath, schema, expected);
}

@Test
public void testDataTypes() throws IOException, ParseException {
    final List<RecordField> fields = new ArrayList<>();
    for (final RecordFieldType fieldType : RecordFieldType.values()) {
        if (fieldType == RecordFieldType.CHOICE) {
            final List<DataType> possibleTypes = new ArrayList<>();
            possibleTypes.add(RecordFieldType.INT.getDataType());
            possibleTypes.add(RecordFieldType.LONG.getDataType());
            fields.add(new RecordField(fieldType.name().toLowerCase(), fieldType.getChoiceDataType(possibleTypes)));
        } else if (fieldType == RecordFieldType.MAP) {
            fields.add(new RecordField(fieldType.name().toLowerCase(), fieldType.getMapDataType(RecordFieldType.INT.getDataType())));
        } else {
            fields.add(new RecordField(fieldType.name().toLowerCase(), fieldType.getDataType()));
        }
    }
    final RecordSchema schema = new SimpleRecordSchema(fields);
    final ByteArrayOutputStream baos = new ByteArrayOutputStream();
    final DateFormat df = new SimpleDateFormat("yyyy/MM/dd HH:mm:ss.SSS");
    df.setTimeZone(TimeZone.getTimeZone("gmt"));
    final long time = df.parse("2017/01/01 17:00:00.000").getTime();
    final Map<String, Object> map = new LinkedHashMap<>();
    map.put("height", 48);
    map.put("width", 96);
    final Map<String, Object> valueMap = new LinkedHashMap<>();
    valueMap.put("string", "string");
    valueMap.put("boolean", true);
    valueMap.put("byte", (byte) 1);
    valueMap.put("char", 'c');
    valueMap.put("short", (short) 8);
    valueMap.put("int", 9);
    valueMap.put("bigint", BigInteger.valueOf(8L));
    valueMap.put("long", 8L);
    valueMap.put("float", 8.0F);
    valueMap.put("double", 8.0D);
    valueMap.put("decimal", BigDecimal.valueOf(8.1D));
    valueMap.put("date", Date.valueOf("2017-01-01"));
    valueMap.put("time", new Time(time));
    valueMap.put("timestamp", new Timestamp(time));
    valueMap.put("record", null);
    valueMap.put("array", null);
    valueMap.put("enum", null);
    valueMap.put("choice", 48L);
    valueMap.put("map", map);
    final Record record = new MapRecord(schema, valueMap);
    final RecordSet rs = RecordSet.of(schema, record);
    try (final WriteJsonResult writer = new WriteJsonResult(Mockito.mock(ComponentLog.class), schema, new SchemaNameAsAttribute(), baos, true, NullSuppression.NEVER_SUPPRESS, OutputGrouping.OUTPUT_ARRAY, RecordFieldType.DATE.getDefaultFormat(), RecordFieldType.TIME.getDefaultFormat(), RecordFieldType.TIMESTAMP.getDefaultFormat())) {
        writer.write(rs);
    }
    final String output = baos.toString("UTF-8");
    final String expected = new String(Files.readAllBytes(Paths.get("src/test/resources/json/output/dataTypes.json")));
    assertEquals(StringUtils.deleteWhitespace(expected), StringUtils.deleteWhitespace(output));
}

